    21  bool Address::IsRoutingLocator(void) const
    22  {
    23      return (mFields.m16[4] == HostSwap16(0x0000) && mFields.m16[5] == HostSwap16(0x00ff) &&
    24              mFields.m16[6] == HostSwap16(0xfe00) && mFields.m8[14] < kAloc16Mask &&
    25              (mFields.m8[14] & kRloc16ReservedBitMask) == 0);
    26  }
