    28  bool Address::IsAnycastRoutingLocator(void) const
    29  {
    30      return (mFields.m16[4] == HostSwap16(0x0000) && mFields.m16[5] == HostSwap16(0x00ff) &&
    31              mFields.m16[6] == HostSwap16(0xfe00) && mFields.m8[14] == kAloc16Mask);
    32  }
