    34  bool Address::IsAnycastServiceLocator(void) const
    35  {
    36      return IsAnycastRoutingLocator() && (mFields.m16[7] >= HostSwap16(Mle::kAloc16ServiceStart)) &&
    37             (mFields.m16[7] <= HostSwap16(Mle::kAloc16ServiceEnd));
