    45  bool Address::IsReservedSubnetAnycast(void) const
    46  {
    47      return (mFields.m32[2] == HostSwap32(0xfdffffff) && mFields.m16[6] == 0xffff && mFields.m8[14] == 0xff &&
    48              mFields.m8[15] >= 0x80);
